use Filament\Http\Middleware\Authenticate;
use Filament\Http\Middleware\AuthenticateSession;
use Filament\Http\Middleware\DisableBladeIconComponents;
use Filament\Http\Middleware\DispatchServingFilamentEvent;
use Filament\Pages\Dashboard;
use Filament\Pages\Enums\SubNavigationPosition;
use Filament\Panel;
use Filament\PanelProvider;
use Filament\Support\Enums\Width;
use Filament\Support\Facades\FilamentColor;
use Filament\View\PanelsRenderHook;
use Filament\Widgets\AccountWidget;
use Gsferro\FilamentOdometerEasy\FilamentOdometerEasyPlugin;
use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
use Illuminate\Cookie\Middleware\EncryptCookies;
use Illuminate\Foundation\Http\Middleware\PreventRequestForgery;
use Illuminate\Routing\Middleware\SubstituteBindings;
use Illuminate\Session\Middleware\StartSession;
use Illuminate\Support\Facades\Blade;
use Illuminate\Support\Facades\Log;
use Illuminate\View\Middleware\ShareErrorsFromSession;
use Jeffgreco13\FilamentBreezy\BreezyCore;
use LaBoiteACode\FilamentDashboardWidgets\FilamentDashboardWidgetsPlugin;
use lockscreen\FilamentLockscreen\Lockscreen;
use Prodstarter\FilamentNotificationCenter\FilamentNotificationCenterPlugin;
use pxlrbt\FilamentEnvironmentIndicator\EnvironmentIndicatorPlugin;
use Wezlo\FilamentSearchSpotlight\Categories\ActionsCategory;
use Wezlo\FilamentSearchSpotlight\Categories\RecordsCategory;
use Wezlo\FilamentSearchSpotlight\FilamentSearchSpotlightPlugin;

/**
 * Painel APP — a operação de negócio. Vem vazio de propósito: é aqui que cada
 * novo projeto constrói suas features (Resources em app/Filament/App/).
 * Acesso: qualquer usuário autenticado — ajuste em User::canAccessPanel().
 */
class AppPanelProvider extends PanelProvider
{
    public function panel(Panel $panel): Panel
    {
        $panel
            ->default()
            ->id('app')
            ->path('app')
            ->login()
            ->passwordReset()
            ->brandName(config('app.name'))
            ->sidebarCollapsibleOnDesktop()
            ->maxContentWidth(Width::Full)
            ->subNavigationPosition(SubNavigationPosition::Top)
            ->databaseNotifications()
            ->databaseNotificationsPolling(config('broadcasting.default') === 'reverb' ? null : '30s')
            ->discoverResources(in: app_path('Filament/App/Resources'), for: 'App\Filament\App\Resources')
            ->discoverPages(in: app_path('Filament/App/Pages'), for: 'App\Filament\App\Pages')
            ->discoverWidgets(in: app_path('Filament/App/Widgets'), for: 'App\Filament\App\Widgets')
            ->pages([
                Dashboard::class,
                ConvitesRecebidos::class,
            ])
            ->widgets([
                AccountWidget::class,
            ])
            // Chat do assistente embarcado em TODA tela deste painel. Render hook (e não um
            // widget de dashboard) porque a superfície precisa acompanhar o usuário em
            // qualquer página. O próprio componente renderiza vazio quando não há usuário
            // autenticado — o hook também roda na tela de login.
            // Para tirar o assistente do painel, remova estas linhas; para tê-lo no admin ou
            // no infra, replique-as no PanelProvider correspondente.
            ->renderHook(
                PanelsRenderHook::BODY_END,
                fn (): string => Blade::render('@livewire(\'assistente-chat-widget\')'),
            )
            ->bootUsing(function (Panel $panel): void {
                // Registra as sugestões "Criar X" no request, com auth já resolvido.
                AcoesDeCriacao::registrar();

                /*
                 * A cor da organização corrente.
                 *
                 * `FilamentColor::register()` com Closure, e NÃO `$panel->colors()`. Os dois
                 * aceitam Closure na assinatura, o que os faz parecer equivalentes — não são:
                 * `Panel::boot()` faz `FilamentColor::register($this->getColors())`
                 * (vendor/filament/filament/src/Panel.php:95) e o `getColors()` do painel avalia
                 * a Closure ali mesmo (Panel/Concerns/HasColors.php:31). Como o `Panel::boot()` é
                 * disparado pelo middleware `panel:{id}`/`SetUpPanel`, que é o PRIMEIRO da pilha
                 * (HasMiddleware.php:97-103), o `IdentifyTenant` ainda não rodou e
                 * `Filament::getTenant()` é sempre null. O código pareceria certo, rodaria sem
                 * erro e nunca aplicaria cor.
                 *
                 * O `register()` guarda a Closure e a avalia em `getColors()`
                 * (ColorManager.php:80), chamado por `AssetManager::renderStyles()`
                 * (AssetManager.php:286) — o `@filamentStyles`, no render do <head>, depois de
                 * todo middleware. É a única janela que serve.
                 *
                 * A guarda de painel não é defensiva, é obrigatória: `FilamentColor` é GLOBAL,
                 * não por painel. Sem ela, a cor de um cliente pintaria /admin e /infra também.
                 *
                 * Uma cor, não uma paleta: o ColorManager chama `Color::generatePalette()` sozinho
                 * quando recebe string (ColorManager.php:84-85).
                 *
                 * Ver ADR-02 da wiki `identidade-visual-da-organizacao`.
                 */
                FilamentColor::register(function (): array {
                    $tenant = Filament::getTenant();

                    // `instanceof Tenant` e não `?->`: `getTenant()` devolve `?Model`, e o model de
                    // tenancy é configurável — o narrowing é guarda real, não cerimônia de tipo.
                    if (Filament::getCurrentPanel()?->getId() !== 'app'
                        || ! $tenant instanceof Tenant
                        || blank($tenant->cor_primaria)) {
                        // Array vazio é o neutro: `getColors()` faz foreach sobre o resultado
                        // (ColorManager.php:82), então nada é sobrescrito e o default sobrevive.
                        return [];
                    }

                    Log::channel('tenancy')->debug(
                        '[AppPanelProvider@bootUsing] Cor da organização aplicada | tenant: '.$tenant->getKey(),
                        [
                            'tenant_id'    => $tenant->getKey(),
                            'tenant_slug'  => $tenant->slug,
                            'cor_primaria' => $tenant->cor_primaria,
                        ],
                    );

                    return ['primary' => $tenant->cor_primaria];
                });

                // "Bloquear sessão" logo abaixo do "Meu perfil" — ver
                // TelaBloqueio::itemDeMenu(). A guarda espelha a do plugin: com o
                // kill-switch desligado a rota não existe e o item estouraria no render.
                if (config('lockscreen.enabled')) {
                    $panel->userMenuItems([TelaBloqueio::itemDeMenu($panel->getId())]);
                }

                /*
                 * Convites recebidos, com a contagem das ofertas pendentes. Registrado
                 * aqui, e não em `->pages()`, porque o caminho é o menu do usuário: a
                 * página fica fora da navegação lateral e só aparece quando há algo a
                 * decidir. `itemDeMenu()` já cuida do `visible()`.
                 */
                $panel->userMenuItems([ConvitesRecebidos::itemDeMenu()]);
            })
            ->plugins([
                FilamentSearchSpotlightPlugin::make()
                    ->keyBinding(['mod+k'])
                    ->disableDefaultGlobalSearch()
                    ->resultLimitPerCategory(5)
                    ->actionsEnabled()
                    ->disableCreateActions()
                    ->placeholder('Buscar registros e telas...')
                    // As categorias do vendor NÃO checam canAccess(); as nossas checam.
                    ->categories([
                        RecordsCategory::class,
                        ResourcesAutorizadasCategory::class,
                        PagesAutorizadasCategory::class,
                        // Lê o registry alimentado por AcoesDeCriacao (as sugestões "Criar X").
                        ActionsCategory::class,
                    ]),

                AuthDesignerPlugin::make()
                    ->login(fn (AuthPageConfig $config): AuthPageConfig => $config
                        // A nossa tela de login: a única diferença é não oferecer
                        // "Cadastre-se", que o Filament acrescenta sozinho assim que o
                        // painel ganha registro.
                        ->usingPage(TelaLogin::class)
                        ->media(asset('images/auth/login.svg'), alt: config('app.name'))
                        ->mediaPosition(MediaPosition::Left)
                        ->mediaSize('70%')
                        ->themeToggle()
                    )
                    /*
                     * A tela de aceite do convite — a ÚNICA rota pública deste painel
                     * além do login. Sem token válido na query string ela recusa e
                     * manda para o login (App\Filament\Pages\Auth\RegistroPorConvite).
                     *
                     * Passa pelo PLUGIN, e não por `$panel->registration(...)` direto:
                     * é o plugin que grava a chave 'registration' no
                     * AuthDesignerConfigRepository (AuthDesignerPlugin.php:92-94). Sem
                     * ela o repositório cai em `new AuthPageConfig`
                     * (AuthDesignerConfigRepository.php:80) e a tela nasce sem mídia e
                     * sem alternador de tema — diferente do login ao lado, sem erro
                     * nenhum. Ver ADR-06.
                     *
                     * Para fechar o cadastro por completo, remova este bloco: a rota
                     * deixa de existir e a superfície pública desaparece.
                     */
                    ->registration(fn (AuthPageConfig $config): AuthPageConfig => $config
                        ->usingPage(RegistroPorConvite::class)
                        ->media(asset('images/auth/login.svg'), alt: config('app.name'))
                        ->mediaPosition(MediaPosition::Left)
                        ->mediaSize('70%')
                        ->themeToggle()
                    ),

                BreezyCore::make()
                    ->myProfile(shouldRegisterUserMenu: true, hasAvatars: true, slug: 'meu-perfil', userMenuLabel: 'Meu perfil')
                    ->enableTwoFactorAuthentication(),

                // Obrigatório em todos os painéis — ver nota no AdminPanelProvider.
                Lockscreen::make()
                    ->enablePlugin((bool) config('lockscreen.enabled'))
                    ->enableIdleTimeout((int) config('lockscreen.idle_timeout'))
                    ->enableRateLimit(limit: 5, decayMinutes: 5, forceLogout: true),

                // Bases prontas de widgets de dashboard (funil, timeline, metas,
                // segment bar...) para os indicadores do seu negócio.
                FilamentDashboardWidgetsPlugin::make(),

                EnvironmentIndicatorPlugin::make()
                    ->visible(fn (): bool => ! app()->isProduction()),

                FilamentOdometerEasyPlugin::make()
                    ->delay(1000)
                    ->duration(1500)
                    ->badgeOnCollapsedSidebar(),

                // Colunas redimensionáveis/fixáveis. Os defaults de tabela ficam em
                // App\Providers\Concerns\ConfiguraFilamentGlobal; aqui só a persistência.
                ResizedColumnPlugin::make()
                    ->preserveOnSession(),

                FilamentNotificationCenterPlugin::make(),
            ])
            /*
             * Gatilho da busca ⌘K, no lugar exato do campo nativo.
             *
             * GLOBAL_SEARCH_BEFORE (e não USER_MENU_BEFORE, que renderiza
             * DENTRO do dropdown do usuário): o hook é emitido pela topbar
             * incondicionalmente — o `disableDefaultGlobalSearch()` guarda o
             * componente Livewire da busca, não o hook. Então a topbar mantém
             * a mesma aparência de sempre, e o clique abre o overlay.
             */
            ->renderHook(
                PanelsRenderHook::GLOBAL_SEARCH_BEFORE,
                fn (): string => view('filament.spotlight-trigger')->render(),
            )
            ->middleware([
                EncryptCookies::class,
                AddQueuedCookiesToResponse::class,
                StartSession::class,
                AuthenticateSession::class,
                ShareErrorsFromSession::class,
                PreventRequestForgery::class,
                SubstituteBindings::class,
                DisableBladeIconComponents::class,
                DispatchServingFilamentEvent::class,
            ])
            ->authMiddleware([
                Authenticate::class,
            ]);

        /*
         * Multi-tenancy (opt-in) — ligue com `php artisan kit:tenancy`.
         *
         * Declarado DEPOIS de plugins() e middleware() de propósito: o
         * ->tenant() reescreve as rotas do painel para /app/{tenant}, e plugin
         * registrado depois disso não enxerga o prefixo.
         *
         * `IdentifyTenant` NÃO entra na lista: o Filament já o registra sozinho.
         * O tenantMiddleware recebe só o middleware do kit, e `isPersistent`
         * é o que o faz rodar também nos requests AJAX do Livewire — sem isso
         * o contexto de papéis se perde na primeira interação de tabela.
         *
         * Sem `->tenantRegistration()` de propósito: quem cria tenant é o
         * administrador, em /admin. Ligar o auto-cadastro deixaria qualquer
         * usuário autenticado criar tenants pelo painel de negócio.
         */
        if (config('kit.tenancy.enabled')) {
            $panel
                ->tenant(Tenant::class, slugAttribute: 'slug')
                ->tenantMiddleware([DefinirTenantDePermissoes::class], isPersistent: true);
        }

        return $panel;
    }
}

<?php

namespace Tests;

use App\Models\Tenant;
use Illuminate\Foundation\Application;
use Illuminate\Foundation\Testing\RefreshDatabaseState;
use Illuminate\Foundation\Testing\TestCase as BaseTestCase;
use Illuminate\Support\Arr;
use Illuminate\Support\Facades\Artisan;
use Spatie\Permission\PermissionRegistrar;

/**
 * Base dos testes do kit — e o único lugar que decide o modo de tenancy da
 * execução, por `usaTenancy()`.
 *
 * O modo mora em TRÊS chaves que precisam concordar, e cada uma tem seu prazo:
 *
 *   1. `kit.tenancy.enabled`, antes do BOOT — o `AppPanelProvider` a lê para
 *      registrar (ou não) as rotas do painel com o segmento `/{tenant}`.
 *   2. `permission.teams` + `filament-shield.tenant_model`, antes das
 *      MIGRATIONS — a migration do spatie lê a primeira em tempo de execução
 *      para criar (ou não) as colunas de team.
 *   3. o contexto de papéis do `PermissionRegistrar`, que é singleton e lê
 *      `permission.teams` no construtor.
 *
 * Elas não vêm do mesmo lugar, e é aí que saíam de sincronia: a primeira é env
 * (`KIT_TENANCY`), as outras duas são arquivos que o `kit:tenancy` reescreve em
 * DISCO. Num projeto com a tenancy ligada, `permission.teams` chegava aqui como
 * `true` mesmo nas suítes single-tenant — e como ninguém fixava o contexto de
 * papéis (o `KitServiceProvider` só o faz com `kit.tenancy.enabled`), atribuir
 * papel estourava `NOT NULL constraint failed: model_has_roles.team_id`.
 */
abstract class TestCase extends BaseTestCase
{
    /**
     * Modo de tenancy com que o schema em memória foi migrado nesta execução.
     * `null` = ainda não migrou.
     */
    private static ?bool $schemaMigradoComTenancy = null;

    /** Sobrescrito por Tests\TenancyTestCase. */
    protected function usaTenancy(): bool
    {
        return false;
    }

    /**
     * A flag vai para o AMBIENTE, antes do bootstrap.
     *
     * O `AppPanelProvider` lê `kit.tenancy.enabled` durante o boot para decidir
     * se registra as rotas do painel com o segmento `/{tenant}`. Config ajustada
     * depois de `parent::createApplication()` chega tarde: as rotas já existem
     * sem o segmento, e todo `/app/{slug}` responde 404.
     */
    public function createApplication(): Application
    {
        /*
         * Cache de config e de rotas ficam FORA de alcance nos testes.
         *
         * Os dois congelam decisões de um ambiente: com `bootstrap/cache/config.php`
         * no lugar, o `env()` nem é consultado e a flag escrita logo abaixo não tem
         * efeito nenhum — a tenancy volta a ligar, o painel /app vira /app/{tenant}
         * e a suíte do kit falha com 404 em `GET /app`, sem pista da causa.
         *
         * Apontar as duas chaves para arquivos que não existem faz o Laravel
         * bootar da fonte. Nada é apagado: o cache do projeto continua no lugar.
         */
        $this->definirEnv('APP_CONFIG_CACHE', 'bootstrap/cache/config.testing.php');
        $this->definirEnv('APP_ROUTES_CACHE', 'bootstrap/cache/routes-v7.testing.php');

        $this->definirEnv('KIT_TENANCY', $this->usaTenancy() ? 'true' : 'false');

        $app = parent::createApplication();

        /*
         * As duas chaves de DISCO, alinhadas com o modo desta execução.
         *
         * Aqui ainda é antes das migrations: o RefreshDatabase roda no
         * `setUpTraits()`, depois deste método. Ajustar `permission.teams` num
         * `beforeEach` seria tarde — o schema já teria sido criado.
         */
        $app['config']->set('permission.teams', $this->usaTenancy());
        $app['config']->set('filament-shield.tenant_model', $this->usaTenancy() ? Tenant::class : null);

        /*
         * O PermissionRegistrar já foi resolvido durante o boot, lendo o
         * `permission.teams` do arquivo — precisa ser descartado para renascer
         * sabendo do modo. Com teams ligado, o contexto global de papéis também
         * precisa ser fixado à mão: o `KitServiceProvider::configureTenancy()`
         * rodou no boot, quando esta config ainda não existia.
         */
        $app->forgetInstance(PermissionRegistrar::class);

        if ($this->usaTenancy()) {
            $app->make(PermissionRegistrar::class)->setPermissionsTeamId(Tenant::CONTEXTO_GLOBAL);
        }

        return $app;
    }

    /**
     * Escreve no ambiente do processo, antes do bootstrap.
     *
     * O repositório de env do Laravel é imutável, então valor já presente em
     * `$_SERVER` vence o que estiver no `.env` — é o que permite alternar os dois
     * modos de tenancy dentro da mesma execução de testes.
     */
    private function definirEnv(string $chave, string $valor): void
    {
        putenv("{$chave}={$valor}");
        $_ENV[$chave]    = $valor;
        $_SERVER[$chave] = $valor;
    }

    /**
     * O `RefreshDatabase` migra UMA vez por processo e reaproveita o schema em
     * todos os testes seguintes. Isso quebra quando a suíte mistura os dois
     * modos do kit: a migration de permissões do spatie cria (ou não) as
     * colunas de team conforme `permission.teams`, então o primeiro teste a
     * rodar decidiria o schema de todos os outros — e o outro modo falharia
     * com violação de NOT NULL, sem relação com o que está sendo testado.
     *
     * Aqui o schema é invalidado só quando o modo MUDA. Numa execução de
     * `--group=kit` isso custa uma migration extra na virada, não uma por
     * teste.
     */
    protected function setUp(): void
    {
        if (self::$schemaMigradoComTenancy !== $this->usaTenancy()) {
            RefreshDatabaseState::$migrated = false;
            self::$schemaMigradoComTenancy  = $this->usaTenancy();
        }

        parent::setUp();
    }

    /**
     * Semeia por `Artisan::call`, não pelo `$this->artisan()` do Laravel.
     *
     * O `seed()` padrão passa por `PendingCommand`, que **liga um mock de
     * `OutputStyle` no container** para poder afirmar sobre a saída. Todo comando
     * disparado DE DENTRO do seeder resolve esse mock — e o mock é
     * `shouldIgnoreMissing()`, ou seja, engole as chamadas em vez de executá-las.
     *
     * O efeito prático no kit era grave e silencioso: o `ShieldPermissionsSeeder`
     * chama `shield:generate`, e sob `$this->seed()` ele terminava com exit 0,
     * imprimia "79 permissions generated" e gravava **zero** linhas na tabela
     * `permissions`. Toda a suíte rodava sem uma única permission no banco desde
     * sempre, e nada acusava: os testes autenticavam como `master_global`, que
     * vence pelo `Gate::before` justamente sem precisar de permission.
     *
     * Medido: `$this->seed(ShieldPermissionsSeeder::class)` → 0 permissions;
     * `Artisan::call('db:seed', ...)` com o mesmo seeder → 186.
     *
     * @param  class-string|array<int, class-string>  $class
     */
    public function seed($class = 'Database\\Seeders\\DatabaseSeeder'): static
    {
        foreach (Arr::wrap($class) as $seeder) {
            Artisan::call('db:seed', [
                '--class'          => $seeder,
                '--force'          => true,
                '--no-interaction' => true,
            ]);
        }

        return $this;
    }
}

<?php

namespace Database\Seeders;

use Filament\Facades\Filament;
use Filament\Panel;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Facade;
use Illuminate\Support\Facades\Schema;
use Spatie\Permission\PermissionRegistrar;

/**
 * Permissions do Shield geradas por SEEDER, não por `shield:generate` na mão.
 *
 * O comando do Shield é interativo e falha em modo não-interativo (é o que quebraria o
 * `composer create-project` no Windows). Aqui a geração roda com `--no-interaction` e,
 * se ainda assim falhar num painel, o kit segue instalando: o master_global passa pelo
 * Gate::before e os papéis são criados pelo PapeisSeeder de qualquer forma.
 *
 * ## Um painel de cada vez
 *
 * O `shield:generate` só enxerga o painel corrente (`discovery.discover_all_*` está
 * `false` nas três chaves). Até a versão 0.10.0 este seeder passava `--panel=admin` e
 * mais nada — resultado: as permissions dos Resources de `/app` e `/infra` nunca
 * chegaram a existir no banco, e as telas desses painéis só abriam para o master_global.
 *
 * O `forgetInstance` entre as voltas é obrigatório: `FilamentShield` é `scoped` e memoiza
 * com `once()`, então sem descartá-lo os três painéis geram o conjunto do primeiro.
 *
 * Rode novamente depois de criar seus Resources:
 *   php artisan db:seed --class=Database\\Seeders\\ShieldPermissionsSeeder
 */
class ShieldPermissionsSeeder extends Seeder
{
    public function run(): void
    {
        if (! Schema::hasTable('permissions')) {
            $this->command->warn('Tabela `permissions` ausente — rode as migrations antes.');

            return;
        }

        $anterior = Filament::getCurrentPanel();

        foreach (array_keys(Filament::getPanels()) as $painel) {
            $this->gerarPara((string) $painel);
        }

        if ($anterior instanceof Panel) {
            Filament::setCurrentPanel($anterior);
        }

        app(PermissionRegistrar::class)->forgetCachedPermissions();
    }

    /** Falhar num painel não pode abortar os outros. */
    private function gerarPara(string $painel): void
    {
        // Instância limpa a cada painel: o Shield é `scoped` e memoiza com `once()`, e a
        // facade ainda guarda o objeto em `Facade::$resolvedInstance`. Sem os dois
        // descartes, as três voltas geram as permissions do primeiro painel.
        app()->forgetInstance('filament-shield');
        Facade::clearResolvedInstance('filament-shield');

        try {
            Artisan::call('shield:generate', [
                '--all'   => true,
                '--panel' => $painel,

                /*
                 * Policy que já existe não é reescrita.
                 *
                 * O `shield:generate` escreve as policies com o estilo dele, não com o do
                 * Pint — e este seeder roda em todo `beforeEach` da suíte. Sem esta flag,
                 * rodar os testes deixa `app/Policies/*.php` reformatado na árvore de
                 * trabalho: `composer test` falha no `lint:check` da execução seguinte, e
                 * o `kit:update` recusa a árvore suja. Também é o que torna o seeder
                 * idempotente de verdade: quem editou uma policy à mão não a perde ao
                 * gerar as permissões de um Resource novo.
                 */
                '--ignore-existing-policies' => true,

                '--no-interaction' => true,
            ]);
        } catch (\Throwable $e) {
            $this->command->warn(
                "shield:generate não pôde rodar no painel {$painel} (".$e->getMessage().'). '
                ."Gere as permissions depois com: php artisan shield:generate --all --panel={$painel}"
            );
        }
    }
}

<?php

namespace App\Traits;

use App\Models\Tenant;
use Filament\Facades\Filament;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Model que pertence a um tenant.
 *
 * Use em TODA model do negócio quando o projeto roda em modo multi-tenant
 * (`php artisan kit:tenancy`). Ela entrega três coisas:
 *
 *   1. a relação `tenant()` — que é o `ownershipRelationship` que o Filament
 *      procura para escopar os resources sozinho;
 *   2. um escopo global que recorta as queries pelo tenant corrente;
 *   3. o preenchimento automático de `tenant_id` ao criar.
 *
 * ## Por que a trait existe, se o Filament já escopa
 *
 * A documentação do Filament é explícita: *"A tenant-aware resource has to
 * exist in the panel with tenancy enabled for the resource's model to have the
 * global scope applied. If you want to scope the queries for a model that does
 * not have a corresponding resource, you must use middleware to apply
 * additional global scopes."*
 *
 * Ou seja: model consultada em job, comando, listener, widget ou API — sem
 * passar por um Resource — fica de fora do escopo do Filament. É exatamente aí
 * que vaza dado de um tenant para outro, em silêncio. Esta trait fecha o
 * buraco no próprio model, que é onde a garantia não depende de ninguém
 * lembrar de nada.
 *
 * Em model que TEM resource, os dois escopos coexistem: aplicam a mesma
 * condição, então a query só repete o filtro — sem efeito colateral.
 *
 * ## Checklist ao usar
 *
 *   1. migration com `$table->foreignId('tenant_id')->constrained()`;
 *   2. model usa esta trait;
 *   3. `tenant_id` fica FORA do `$fillable` — quem preenche é a trait;
 *   4. no form do resource, use `->scopedUnique()` em vez de `->unique()`
 *      (a regra `unique` do Laravel não enxerga o tenant).
 *
 * ## Limites (leia antes de confiar)
 *
 * - **Sem tenant, sem escopo.** Fora de um request de painel (job, comando,
 *   seeder, tinker) `Filament::getTenant()` é null e a query volta a ser
 *   global. É deliberado: um job que roda para todos os tenants precisa
 *   enxergar todos. Quando o job for de UM tenant, filtre explicitamente —
 *   `Model::where('tenant_id', $id)` — ou chame `Filament::setTenant()`.
 * - **Escopo não é autorização.** Policies continuam obrigatórias, pela mesma
 *   razão que `TemUuid` não substitui policy.
 * - **`withoutGlobalScopes()` derruba este escopo junto com os outros.** A
 *   própria doc do Filament avisa que isso "can lead to data leakage". Para
 *   uma query deliberadamente global, remova só este:
 *   `Model::withoutGlobalScope('tenant')`.
 */
trait BelongsToTenant
{
    public static function bootBelongsToTenant(): void
    {
        static::addGlobalScope('tenant', function (Builder $query): void {
            $tenant = Filament::getTenant();

            if ($tenant instanceof Tenant) {
                $query->where($query->getModel()->qualifyColumn('tenant_id'), $tenant->getKey());
            }
        });

        static::creating(function (self $model): void {
            $tenant = Filament::getTenant();

            if ($tenant instanceof Tenant && blank($model->tenant_id)) {
                $model->tenant_id = $tenant->getKey();
            }
        });
    }

    /** @return BelongsTo<Tenant, $this> */
    public function tenant(): BelongsTo
    {
        return $this->belongsTo(Tenant::class);
    }
}

